def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    recip_rep = observation['recipient_reputation']
    # Own reputation determines strictness: high-reputation agents judge more harshly
    strictness = 0.5 * (1 + current_reputation)  # maps [-1,1] to [0,1]
    if action == 'A':
        if recip_rep > 0:
            delta = 0.3 * strictness
        else:
            delta = 0.1 * strictness
        return min(1.0, current_reputation + delta)
    else:
        if recip_rep > 0:
            delta = -0.3 * strictness
        else:
            delta = -0.1 * strictness
        return max(-1.0, current_reputation + delta)

def decide(recipient_reputation, round_num, my_history):
    # Become more cautious over time: threshold starts low (forgiving) and increases
    threshold = 0.3 + 0.2 * min(round_num / 20, 1.0)
    return recipient_reputation > threshold
